"use client";

import { useId, useState } from "react";
import {
  CRYPTO_RANGE_LABEL,
  CRYPTO_RANGES,
  formatCompactMoney,
  formatCryptoPrice,
  formatPercent,
  summarizeCrypto,
} from "@/features/crypto/crypto-schema";
import { CARD_FRAME as SHARED_CARD_FRAME } from "@/lib/card-frame";
import { cn } from "@/lib/utils";
import type { CryptoData, CryptoRange } from "@/features/crypto/crypto-schema";

export type CryptoCardState = "streaming" | "loading" | "ready" | "error";

export interface CryptoCardProperties {
  readonly state: CryptoCardState;
  /**
  The symbol from the props, shown before the data arrives.
  */
  readonly symbol?: string;
  readonly data?: CryptoData;
  readonly error?: string;
  /**
  Loads another range when the reader switches it. Without it, the switch is hidden and the card shows the range it was given.
  */
  readonly loadRange?: (
    symbol: string,
    range: CryptoRange
  ) => Promise<CryptoData>;
  readonly className?: string;
}

const CARD_FRAME = `${SHARED_CARD_FRAME} w-full max-w-sm`;

const LABEL = "text-muted-foreground text-xs";

const UP = "text-emerald-600 dark:text-emerald-400";
const DOWN = "text-red-600 dark:text-red-400";
const UP_PILL = "bg-emerald-500/12 text-emerald-700 dark:text-emerald-400";
const DOWN_PILL = "bg-red-500/12 text-red-700 dark:text-red-400";

const CHART_WIDTH = 200;
const CHART_HEIGHT = 80;
const LABEL_EDGE_PERCENT = 30;

const RANGE_SPAN: Record<CryptoRange, string> = {
  "1m": "the past month",
  "1w": "the past week",
  "1y": "the past year",
  "24h": "the past 24 hours",
  all: "all time",
};

/**
How the time under the pointer reads for each range: the hour while the line covers days, the date over months, the month and year over all time.
*/
const POINT_TIME: Record<CryptoRange, Intl.DateTimeFormatOptions> = {
  "1m": { day: "numeric", hour: "numeric", month: "short" },
  "1w": { hour: "numeric", weekday: "short" },
  "1y": { day: "numeric", month: "short", year: "numeric" },
  "24h": { hour: "numeric", minute: "2-digit", weekday: "short" },
  all: { month: "short", year: "numeric" },
};

const CoinLogo = ({ data }: { readonly data: CryptoData }) => {
  const [failed, setFailed] = useState(false);
  if (failed) {
    return (
      <div
        aria-hidden
        className="bg-muted text-muted-foreground flex size-10 shrink-0 items-center justify-center rounded-full text-sm font-semibold"
      >
        {data.symbol.charAt(0)}
      </div>
    );
  }
  return (
    // eslint-disable-next-line @next/next/no-img-element, react-doctor/nextjs-no-img-element, jsx-a11y/no-noninteractive-element-interactions -- next/image would force the logo host into the installer's next.config; onError swaps in the letter tile, it is not a user interaction
    <img
      src={data.image}
      alt=""
      width={40}
      height={40}
      loading="lazy"
      onError={() => setFailed(true)}
      className="size-10 shrink-0 rounded-full object-cover"
    />
  );
};

const ChangePill = ({ data }: { readonly data: CryptoData }) => {
  const isUp = data.changePercent >= 0;
  return (
    <p
      className={cn(
        "inline-flex w-fit items-center gap-1 rounded-md px-1.5 py-0.5 text-sm font-semibold tabular-nums",
        isUp ? UP_PILL : DOWN_PILL
      )}
    >
      <span aria-hidden className="text-[10px]">
        {isUp ? "▲" : "▼"}
      </span>
      <span className="sr-only">{isUp ? "Up" : "Down"}</span>
      {formatPercent(data.changePercent)}
    </p>
  );
};

const Stat = ({
  label,
  value,
}: {
  readonly label: string;
  readonly value: string;
}) => (
  <div className="flex min-w-0 flex-col">
    <dt className={LABEL}>{label}</dt>
    <dd className="truncate text-sm font-semibold tabular-nums">{value}</dd>
  </div>
);

/**
The time under the pointer, in the reader's own time zone. Only reached once someone points at or focuses the chart, so it never runs during server rendering.
*/
function formatPointTime(time: number, range: CryptoRange) {
  const date = new Date(time);
  return date.toLocaleString("en-US", POINT_TIME[range]);
}

/**
"Since Oct 2013" for the all-time line, in UTC so the server and the browser agree.
*/
function formatSince(time: number) {
  const date = new Date(time);
  const since = date.toLocaleDateString("en-US", {
    month: "short",
    timeZone: "UTC",
    year: "numeric",
  });
  return `Since ${since}`;
}

function labelAlignment(xPercent: number) {
  if (xPercent < LABEL_EDGE_PERCENT) {
    return "translate-x-0";
  }
  return xPercent > 100 - LABEL_EDGE_PERCENT
    ? "-translate-x-full"
    : "-translate-x-1/2";
}

/**
The trend line over the chosen range. Point at it, drag across it, or focus it and use the arrow keys to read the price at each point.
*/
const Sparkline = ({
  data,
  className,
}: {
  readonly data: CryptoData;
  readonly className?: string;
}) => {
  const gradientId = useId();
  const [active, setActive] = useState<number | null>(null);
  const { points } = data;
  if (points.length < 2) {
    return <div className="h-20" />;
  }
  const prices = points.map((point) => point.price);
  const min = Math.min(...prices);
  const max = Math.max(...prices);
  const span = max - min || 1;
  const coords = prices.map((price, index) => [
    (index / (prices.length - 1)) * CHART_WIDTH,
    CHART_HEIGHT - 2 - ((price - min) / span) * (CHART_HEIGHT - 4),
  ]);
  const line = coords
    .map(
      ([x, y], index) =>
        `${index === 0 ? "M" : "L"}${x.toFixed(1)},${y.toFixed(1)}`
    )
    .join(" ");

  const last = points.length - 1;
  const indexAt = (clientX: number, box: DOMRect) =>
    Math.round(
      Math.min(Math.max((clientX - box.left) / box.width, 0), 1) * last
    );

  const point = active === null ? null : points[active];
  const xPercent = active === null ? 0 : (active / last) * 100;
  const yPercent =
    active === null ? 0 : (coords[active][1] / CHART_HEIGHT) * 100;

  return (
    // eslint-disable-next-line jsx-a11y/prefer-tag-over-role -- a native range input can't follow the pointer on hover, which is how the chart is read; this keeps the slider semantics and arrow keys
    <div
      tabIndex={0}

      role="slider"
      aria-label={`Price over ${RANGE_SPAN[data.range]}`}
      aria-valuemin={0}
      aria-valuemax={last}
      aria-valuenow={active ?? last}
      aria-valuetext={
        point
          ? `${formatCryptoPrice(point.price, data.currency)} at ${formatPointTime(point.time, data.range)}`
          : summarizeCrypto(data)
      }
      onPointerMove={(event) =>
        setActive(
          indexAt(event.clientX, event.currentTarget.getBoundingClientRect())
        )
      }
      onPointerDown={(event) =>
        setActive(
          indexAt(event.clientX, event.currentTarget.getBoundingClientRect())
        )
      }
      onPointerLeave={() => setActive(null)}
      onFocus={() => setActive((current) => current ?? last)}
      onBlur={() => setActive(null)}
      onKeyDown={(event) => {
        if (!(event.key === "ArrowLeft" || event.key === "ArrowRight")) {
          return;
        }
        event.preventDefault();
        const step = event.key === "ArrowLeft" ? -1 : 1;
        setActive((current) =>
          Math.min(Math.max((current ?? last) + step, 0), last)
        );
      }}
      className={cn(
        "focus-visible:ring-ring relative h-20 w-full cursor-crosshair touch-pan-y rounded outline-none focus-visible:ring-2",
        className
      )}
    >
      <svg
        viewBox={`0 0 ${CHART_WIDTH} ${CHART_HEIGHT}`}
        preserveAspectRatio="none"
        aria-hidden
        className="size-full"
      >
        <defs>
          <linearGradient id={gradientId} x1="0" x2="0" y1="0" y2="1">
            <stop offset="0%" stopColor="currentColor" stopOpacity={0.18} />
            <stop offset="100%" stopColor="currentColor" stopOpacity={0} />
          </linearGradient>
        </defs>
        <path
          d={`${line} L${CHART_WIDTH},${CHART_HEIGHT} L0,${CHART_HEIGHT} Z`}
          fill={`url(#${gradientId})`}
        />
        <path
          d={line}
          fill="none"
          stroke="currentColor"
          strokeWidth={1.5}
          strokeLinejoin="round"
          vectorEffect="non-scaling-stroke"
        />
      </svg>

      {point ? (
        <>
          <div
            aria-hidden
            className="bg-border pointer-events-none absolute inset-y-0 w-px"
            style={{ left: `${xPercent}%` }}
          />
          <div
            aria-hidden
            className="ring-card pointer-events-none absolute size-2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-current ring-2"
            style={{ left: `${xPercent}%`, top: `${yPercent}%` }}
          />
          <div
            aria-hidden
            className={cn(
              "bg-popover text-popover-foreground pointer-events-none absolute -top-2 flex -translate-y-full flex-col rounded-md border px-2 py-1 text-xs whitespace-nowrap shadow-sm",
              labelAlignment(xPercent)
            )}
            style={{ left: `${xPercent}%` }}
          >
            <span className="font-semibold tabular-nums">
              {formatCryptoPrice(point.price, data.currency)}
            </span>
            <span className="text-muted-foreground tabular-nums">
              {formatPointTime(point.time, data.range)}
            </span>
          </div>
        </>
      ) : null}
    </div>
  );
};

const RangeSwitch = ({
  shown,
  onSelect,
}: {
  readonly shown: CryptoRange;
  readonly onSelect: (range: CryptoRange) => void;
}) => (
  <fieldset className="bg-muted flex min-w-0 gap-0.5 rounded-lg p-0.5">
    <legend className="sr-only">Range</legend>
    {CRYPTO_RANGES.map((range) => {
      const isSelected = shown === range;
      return (
        <button
          key={range}
          type="button"
          aria-pressed={isSelected}
          onClick={() => onSelect(range)}
          className={cn(
            "focus-visible:ring-ring rounded-md px-2 py-0.5 text-xs font-medium transition-colors outline-none focus-visible:ring-2",
            isSelected
              ? "bg-background text-foreground shadow-sm"
              : "text-muted-foreground hover:text-foreground"
          )}
        >
          {CRYPTO_RANGE_LABEL[range]}
        </button>
      );
    })}
  </fieldset>
);

const CryptoReady = ({
  data,
  pendingRange,
  rangeError,
  onSelectRange,
}: {
  readonly data: CryptoData;
  readonly pendingRange: CryptoRange | null;
  readonly rangeError: string | null;
  readonly onSelectRange?: (range: CryptoRange) => void;
}) => {
  const isUp = data.changePercent >= 0;
  const firstTime = data.points[0]?.time;
  const note =
    firstTime !== undefined && data.range === "all"
      ? formatSince(firstTime)
      : null;
  return (
    <div className="flex flex-col gap-4">
      <header className="flex items-center justify-between gap-3">
        <div className="flex min-w-0 items-center gap-3">
          <CoinLogo data={data} />
          <p className="truncate text-xl font-semibold">{data.name}</p>
        </div>
        <p className="text-muted-foreground shrink-0 font-mono text-lg">
          {data.symbol}
        </p>
      </header>
      <div className="grid grid-cols-[auto_minmax(0,1fr)] items-end gap-4">
        <div className="flex flex-col gap-3">
          <div className="flex flex-col gap-1">
            <p className="text-2xl font-semibold tabular-nums">
              {formatCryptoPrice(data.price, data.currency)}
            </p>
            <ChangePill data={data} />
          </div>
          <dl className="grid grid-cols-2 gap-x-4">
            <Stat
              label="Market Cap"
              value={formatCompactMoney(data.marketCap, data.currency)}
            />
            <Stat
              label="24h Volume"
              value={formatCompactMoney(data.volume24h, data.currency)}
            />
          </dl>
        </div>
        <div
          className={cn(
            "transition-opacity duration-150",
            pendingRange && "opacity-40"
          )}
        >
          <Sparkline data={data} className={isUp ? UP : DOWN} />
        </div>
      </div>
      <div className="flex items-center justify-between gap-2">
        {onSelectRange ? (
          <RangeSwitch
            shown={pendingRange ?? data.range}
            onSelect={onSelectRange}
          />
        ) : (
          <span className={LABEL}>{CRYPTO_RANGE_LABEL[data.range]}</span>
        )}
        <p className={LABEL} aria-live="polite">
          {rangeError ?? note}
        </p>
      </div>
    </div>
  );
};

const CryptoError = ({
  symbol,
  message = "The crypto price service didn't respond. Try again in a moment.",
}: {
  readonly symbol?: string;
  readonly message?: string;
}) => (
  <div role="alert" className="flex flex-col gap-1">
    <p className="text-sm font-semibold">
      {symbol
        ? `Couldn't load ${symbol.toUpperCase()}`
        : "Couldn't load the price"}
    </p>
    <p className="text-muted-foreground text-xs">{message}</p>
  </div>
);

const Bar = ({ className }: { readonly className?: string }) => (
  <div className={cn("bg-muted animate-pulse rounded", className)} />
);

/**
The card while its data is on the way: the same frame and rows as the ready card, so nothing moves when the price lands. Shows the symbol as soon as it's known (with "…" while the model is still writing it).
*/
export const CryptoCardSkeleton = ({
  symbol,
  streaming = false,
  className,
}: {
  readonly symbol?: string;
  readonly streaming?: boolean;
  readonly className?: string;
}) => (
  <output className={cn(CARD_FRAME, "block", className)}>
    <span className="sr-only">
      {symbol ? `Loading the price of ${symbol}` : "Loading a crypto price"}
    </span>
    <div aria-hidden className="flex flex-col gap-4">
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <Bar className="size-10 rounded-full" />
          <Bar className="h-5 w-24" />
        </div>
        {symbol ? (
          <p className="text-muted-foreground font-mono text-lg">
            {symbol.toUpperCase()}
            {streaming ? <span>…</span> : null}
          </p>
        ) : (
          <Bar className="h-5 w-12" />
        )}
      </div>
      <div className="grid grid-cols-[auto_minmax(0,1fr)] items-end gap-4">
        <div className="flex flex-col gap-3">
          <div className="flex flex-col gap-1">
            <div className="flex h-8 items-center">
              <Bar className="h-6 w-32" />
            </div>
            <Bar className="h-6 w-16 rounded-md" />
          </div>
          <div className="grid grid-cols-2 gap-x-4">
            {["Market Cap", "24h Volume"].map((label) => (
              <div key={label} className="flex flex-col">
                <p className={LABEL}>{label}</p>
                <div className="flex h-5 items-center">
                  <Bar className="h-3.5 w-14" />
                </div>
              </div>
            ))}
          </div>
        </div>
        <Bar className="h-20 w-full" />
      </div>
      <Bar className="h-6 w-44 rounded-lg" />
    </div>
  </output>
);

export const CryptoCard = ({
  state,
  symbol,
  data,
  error,
  loadRange,
  className,
}: CryptoCardProperties) => {
  const [override, setOverride] = useState<CryptoData | null>(null);
  const [pendingRange, setPendingRange] = useState<CryptoRange | null>(null);
  const [rangeError, setRangeError] = useState<string | null>(null);
  const shown = override ?? data;

  const selectRange = async (range: CryptoRange) => {
    if (!(loadRange && shown) || range === shown.range) {
      return;
    }
    setPendingRange(range);
    setRangeError(null);
    try {
      setOverride(await loadRange(shown.symbol, range));
    } catch {
      setRangeError("Couldn't load that range.");
    }
    setPendingRange(null);
  };

  if (state === "ready" && shown) {
    return (
      <section
        aria-label={summarizeCrypto(shown)}
        className={cn(CARD_FRAME, className)}
      >
        <CryptoReady
          data={shown}
          pendingRange={pendingRange}
          rangeError={rangeError}
          onSelectRange={loadRange ? selectRange : undefined}
        />
      </section>
    );
  }
  if (state === "error") {
    return (
      <div className={cn(CARD_FRAME, className)}>
        <CryptoError symbol={symbol} message={error} />
      </div>
    );
  }
  return (
    <CryptoCardSkeleton
      symbol={symbol}
      streaming={state === "streaming"}
      className={className}
    />
  );
};

"use client";

import { useEffect, useState } from "react";
import { CryptoCard } from "@/features/crypto/components/crypto-card";
import { loadCrypto } from "@/features/crypto/crypto-requests";
import { errorMessage } from "@/features/crypto/crypto-schema";
import type { CryptoData, CryptoRange } from "@/features/crypto/crypto-schema";

/**
What came back for one symbol and range. A result for different props reads as still loading, so a new coin never flashes the old one.
*/
type Result =
  | { key: string; status: "ready"; data: CryptoData }
  | { key: string; status: "error"; message: string };

export function LiveCryptoCard({
  symbol,
  range = "24h",
  streaming = false,
  className,
}: {
  readonly symbol?: string;
  readonly range?: CryptoRange;
  /**
  The model is still writing the card's props.
  */
  readonly streaming?: boolean;
  readonly className?: string;
}) {
  const [result, setResult] = useState<Result | null>(null);

  useEffect(() => {
    let isCancelled = false;
    const run = async (wanted: string, key: string) => {
      let next: Result;
      try {
        next = {
          data: await loadCrypto(wanted, range),
          key,
          status: "ready",
        };
      } catch (error) {
        next = {
          key,
          message: errorMessage(error, "Crypto lookup failed."),
          status: "error",
        };
      }
      if (!isCancelled) {
        setResult(next);
      }
    };
    if (!streaming && symbol) {
      run(symbol, `${symbol}:${range}`);
    }
    return () => {
      isCancelled = true;
    };
  }, [symbol, range, streaming]);

  if (streaming || !symbol) {
    return (
      <CryptoCard state="streaming" symbol={symbol} className={className} />
    );
  }
  const current = result?.key === `${symbol}:${range}` ? result : null;
  if (current?.status === "ready") {
    return (
      <CryptoCard
        state="ready"
        data={current.data}
        loadRange={loadCrypto}
        className={className}
      />
    );
  }
  if (current?.status === "error") {
    return (
      <CryptoCard
        state="error"
        symbol={symbol}
        error={current.message}
        className={className}
      />
    );
  }
  return <CryptoCard state="loading" symbol={symbol} className={className} />;
}

import { z } from "zod";
import { CRYPTO_RANGES } from "@/features/crypto/crypto-schema";

export const cryptoCatalogEntry = {
  description:
    "A live crypto price card: the coin's price, its change over the chosen range, market cap, 24-hour volume and a trend line with a 24H/1W/1M/1Y/All switch. It fetches its own data. Use it whenever the user asks about a cryptocurrency's price or how it's doing. Convert coin names to their symbol.",
  props: z.object({
    range: z
      .enum(CRYPTO_RANGES)
      .nullable()
      .describe(
        "Trend line range: 24h, 1w, 1m, 1y or all (since the coin listed). Null for the past 24 hours, unless the user asks about a longer period."
      ),
    symbol: z
      .string()
      .describe(
        'The coin\'s symbol, e.g. "BTC" for Bitcoin or "ETH" for Ethereum.'
      ),
  }),
};

import { listOf } from "@/features/chat/lookup";
import { loadCrypto } from "@/features/crypto/crypto-requests";
import {
  isCryptoRange,
  normalizeCryptoSymbol,
} from "@/features/crypto/crypto-schema";
import type { CardLookup } from "@/features/chat/lookup";

function symbolOf(properties: Record<string, unknown>) {
  return typeof properties.symbol === "string" ? properties.symbol : "";
}

export const cryptoLookup: CardLookup = {
  intent: (symbols) =>
    symbols.length === 1
      ? `The price of ${symbols[0]}`
      : `Prices for ${listOf(symbols)}`,
  load: (properties) =>
    loadCrypto(
      symbolOf(properties),
      isCryptoRange(properties.range) ? properties.range : "24h"
    ),
  sources: () => [
    { href: "https://www.coingecko.com/", label: "coingecko.com" },
  ],
  subject: (properties) => normalizeCryptoSymbol(symbolOf(properties)),
};

import { normalizeCryptoSymbol } from "@/features/crypto/crypto-schema";
import type { CryptoData, CryptoRange } from "@/features/crypto/crypto-schema";

const sharedCryptoRequests = new Map<
  string,
  { expiresAt: number; crypto: Promise<CryptoData> }
>();
const REUSE_MS = 60_000;

function cryptoKey(symbol: string, range: CryptoRange) {
  const coin = normalizeCryptoSymbol(symbol) ?? symbol.trim().toUpperCase();
  return `${coin}:${range}`;
}

async function fetchCrypto(symbol: string, range: CryptoRange) {
  const parameters = new URLSearchParams({ range, symbol });
  const response = await fetch(`/api/crypto?${parameters}`);
  const body = (await response.json()) as CryptoData | { error: string };
  if (!response.ok || "error" in body) {
    throw new Error(
      "error" in body ? body.error : `Crypto request failed: ${response.status}`
    );
  }
  return body;
}

async function requestCrypto(key: string, symbol: string, range: CryptoRange) {
  try {
    return await fetchCrypto(symbol, range);
  } catch (error) {
    sharedCryptoRequests.delete(key);
    throw error;
  }
}

export function loadCrypto(symbol: string, range: CryptoRange = "24h") {
  const key = cryptoKey(symbol, range);
  const hit = sharedCryptoRequests.get(key);
  if (hit && Date.now() < hit.expiresAt) {
    return hit.crypto;
  }
  const crypto = requestCrypto(key, symbol, range);
  sharedCryptoRequests.set(key, { crypto, expiresAt: Date.now() + REUSE_MS });
  return crypto;
}

export function primeCrypto(
  symbol: string,
  range: CryptoRange,
  data: CryptoData
) {
  sharedCryptoRequests.set(cryptoKey(symbol, range), {
    crypto: Promise.resolve(data),
    expiresAt: Infinity,
  });
}

import "server-only";
import type {
  CryptoData,
  CryptoPoint,
  CryptoRange,
} from "@/features/crypto/crypto-schema";

// Server only: CoinGecko's free API allows only a few calls a minute per IP, so every card goes through these caches instead of calling it from the browser.

interface CoinGeckoMarket {
  id: string;
  symbol: string;
  name: string;
  image: string;
  current_price: number;
  market_cap: number;
  total_volume: number;
  price_change_24h: number | null;
  price_change_percentage_24h: number | null;
  last_updated: string;
  sparkline_in_7d?: { price: number[] };
}

interface CoinGeckoChart {
  prices?: [number, number][];
}

interface KrakenOhlc {
  error: string[];
  result?: Record<string, unknown>;
}

const NOT_FOUND = 404;
const BUSY = 503;

/**
A lookup that failed for a reason the reader should hear about, with the HTTP status the route answers: 404 for an unknown coin, 503 while CoinGecko is rate-limiting.
*/
export class CryptoLookupError extends Error {
  readonly status: typeof NOT_FOUND | typeof BUSY;

  constructor(
    status: typeof NOT_FOUND | typeof BUSY,
    message: string,
    options?: ErrorOptions
  ) {
    super(message, options);
    this.name = "CryptoLookupError";
    this.status = status;
  }
}

const busy = () =>
  new CryptoLookupError(
    BUSY,
    "The crypto price service is busy. Try again in a minute."
  );

const CURRENCY = "USD";
const HOUR_MS = 3_600_000;
const MINUTE_MS = 60_000;
const DAY_POINTS = 25;
const TIMEOUT_MS = 8000;
const RATE_LIMITED = 429;
const KRAKEN_WEEK_MINUTES = 10_080;
const KRAKEN_CLOSE = 4;
const MAX_POINTS = 240;

/**
How long each answer stays fresh: the price for a minute, longer ranges for longer, since a year's line barely moves in an hour.
*/
const FRESH_MS = {
  all: 6 * 60 * MINUTE_MS,
  chart: 15 * MINUTE_MS,
  market: MINUTE_MS,
  week: 5 * MINUTE_MS,
} as const;

/**
CoinGecko's chart for each range, in days. "all" asks Kraken first: CoinGecko's free API only goes back a year.
*/
const CHART_DAYS = { "1m": 30, "1w": 7, "1y": 365, all: 365 } as const;

const cache = new Map<
  string,
  { savedAt: number; value?: unknown; pending?: Promise<unknown> }
>();

/**
Answers from the cache while it's fresh, shares a request already in flight, and falls back to the last good answer when the upstream is busy.
*/
function cached<T>(
  key: string,
  freshMs: number,
  load: () => Promise<T>
): Promise<T> {
  const hit = cache.get(key);
  if (hit?.pending) {
    return hit.pending as Promise<T>;
  }
  if (hit?.value !== undefined && Date.now() - hit.savedAt < freshMs) {
    return Promise.resolve(hit.value as T);
  }
  const pending = (async () => {
    try {
      const value = await load();
      cache.set(key, { savedAt: Date.now(), value });
      return value;
    } catch (error) {
      const isBusy =
        error instanceof CryptoLookupError && error.status === BUSY;
      if (isBusy && hit?.value !== undefined) {
        cache.set(key, { savedAt: hit.savedAt, value: hit.value });
        return hit.value as T;
      }
      cache.delete(key);
      throw error;
    }
  })();
  cache.set(key, { ...hit, pending, savedAt: hit?.savedAt ?? 0 });
  return pending;
}

async function fetchJson<T>(url: string): Promise<T> {
  const response = await fetch(url, {
    signal: AbortSignal.timeout(TIMEOUT_MS),
  });
  if (response.status === RATE_LIMITED) {
    throw busy();
  }
  if (!response.ok) {
    throw new Error(`The crypto price service returned ${response.status}.`);
  }
  return (await response.json()) as T;
}

function getMarket(symbol: string) {
  return cached(`market:${symbol}`, FRESH_MS.market, async () => {
    const parameters = new URLSearchParams({
      include_tokens: "top",
      sparkline: "true",
      symbols: symbol.toLowerCase(),
      vs_currency: CURRENCY.toLowerCase(),
    });
    const [coin] = await fetchJson<CoinGeckoMarket[]>(
      `https://api.coingecko.com/api/v3/coins/markets?${parameters}`
    );
    if (!coin) {
      throw new CryptoLookupError(NOT_FOUND, `No coin found for "${symbol}".`);
    }
    return coin;
  });
}

/**
At most MAX_POINTS evenly spaced points, always keeping the first and the last, so a month of hourly prices draws and hovers as smoothly as a day.
*/
function thin(points: readonly CryptoPoint[]): CryptoPoint[] {
  if (points.length <= MAX_POINTS) {
    return [...points];
  }
  const step = (points.length - 1) / (MAX_POINTS - 1);
  return Array.from(
    { length: MAX_POINTS },
    (_, index) => points[Math.round(index * step)]
  );
}

/**
The last 24 hours of CoinGecko's hourly 7-day sparkline, timed back from the last update.
*/
function dayPoints(coin: CoinGeckoMarket, asOf: number): CryptoPoint[] {
  const day = (coin.sparkline_in_7d?.price ?? []).slice(-DAY_POINTS);
  return day.map((price, index) => ({
    price,
    time: asOf - (day.length - 1 - index) * HOUR_MS,
  }));
}

function coinGeckoChart(coin: CoinGeckoMarket, days: number) {
  return cached(
    `chart:${coin.id}:${days}`,
    days === CHART_DAYS["1w"] ? FRESH_MS.week : FRESH_MS.chart,
    async () => {
      const parameters = new URLSearchParams({
        days: String(days),
        vs_currency: CURRENCY.toLowerCase(),
      });
      const chart = await fetchJson<CoinGeckoChart>(
        `https://api.coingecko.com/api/v3/coins/${encodeURIComponent(coin.id)}/market_chart?${parameters}`
      );
      return (chart.prices ?? []).map(([time, price]) => ({ price, time }));
    }
  );
}

/**
Every week since the coin listed on Kraken, or null when Kraken doesn't list it in US dollars.
*/
function krakenHistory(symbol: string) {
  return cached(`all:${symbol}`, FRESH_MS.all, async () => {
    const parameters = new URLSearchParams({
      interval: String(KRAKEN_WEEK_MINUTES),
      pair: symbol + CURRENCY,
    });
    const body = await fetchJson<KrakenOhlc>(
      `https://api.kraken.com/0/public/OHLC?${parameters}`
    );
    const series = Object.entries(body.result ?? {}).find(
      ([key]) => key !== "last"
    )?.[1];
    if (body.error.length > 0 || !Array.isArray(series)) {
      return null;
    }
    return (series as (string | number)[][]).map((candle) => ({
      price: Number(candle[KRAKEN_CLOSE]),
      time: Number(candle[0]) * 1000,
    }));
  });
}

async function rangePoints(
  coin: CoinGeckoMarket,
  symbol: string,
  range: Exclude<CryptoRange, "24h">
): Promise<CryptoPoint[]> {
  if (range === "all") {
    const history = await krakenHistory(symbol);
    if (history && history.length > 1) {
      return history;
    }
  }
  return coinGeckoChart(coin, CHART_DAYS[range]);
}

/**
The live price for a coin over a range. Pass the symbol normalized ("BTC"). The price, market cap and volume come from one cached CoinGecko call shared by every range; the trend line for 24 hours comes with it, longer ranges from CoinGecko's chart, and all time from Kraken.
*/
export async function getCrypto(
  symbol: string,
  range: CryptoRange = "24h"
): Promise<CryptoData> {
  const coin = await getMarket(symbol);
  const asOf = Date.parse(coin.last_updated) || Date.now();
  const price = coin.current_price;
  const history =
    range === "24h"
      ? dayPoints(coin, asOf)
      : await rangePoints(coin, symbol, range);
  const points = thin(history.filter((point) => point.time < asOf));
  points.push({ price, time: asOf });

  const first = points[0].price;
  const isDay = range === "24h";
  const change = isDay
    ? (coin.price_change_24h ?? price - first)
    : price - first;
  const dayPercent = isDay ? coin.price_change_percentage_24h : null;
  const changePercent = dayPercent ?? (change / (price - change || 1)) * 100;

  return {
    asOf,
    change,
    changePercent,
    currency: CURRENCY,
    image: coin.image,
    marketCap: coin.market_cap,
    name: coin.name,
    points,
    price,
    range,
    symbol: coin.symbol.toUpperCase(),
    volume24h: coin.total_volume,
  };
}

export const CRYPTO_RANGES = ["24h", "1w", "1m", "1y", "all"] as const;
export type CryptoRange = (typeof CRYPTO_RANGES)[number];

export const CRYPTO_RANGE_LABEL: Record<CryptoRange, string> = {
  "1m": "1M",
  "1w": "1W",
  "1y": "1Y",
  "24h": "24H",
  all: "All",
};

const RANGE_PERIOD: Record<CryptoRange, string> = {
  "1m": "the past month",
  "1w": "the past week",
  "1y": "the past year",
  "24h": "the past 24 hours",
  all: "all time",
};

export function isCryptoRange(value: unknown): value is CryptoRange {
  return (CRYPTO_RANGES as readonly unknown[]).includes(value);
}

export interface CryptoPoint {
  /**
  Unix time in milliseconds.
  */
  time: number;
  price: number;
}

export interface CryptoData {
  /**
  e.g. "BTC".
  */
  symbol: string;
  /**
  e.g. "Bitcoin".
  */
  name: string;
  /**
  The coin's logo, a square image from CoinGecko.
  */
  image: string;
  /**
  e.g. "USD".
  */
  currency: string;
  /**
  The span the trend line and the change cover.
  */
  range: CryptoRange;
  price: number;
  /**
  Change over the range, in the currency and as a percent.
  */
  change: number;
  changePercent: number;
  marketCap: number;
  /**
  Always the past 24 hours, whatever the range.
  */
  volume24h: number;
  /**
  Prices over the range, oldest first, ending at the current price.
  */
  points: CryptoPoint[];
  /**
  Unix time in milliseconds of the latest price.
  */
  asOf: number;
}

const SYMBOL = /^[A-Z\d]{1,10}$/u;

/**
"btc" and " BTC " both read "BTC". Null when it isn't a coin symbol.
*/
export function normalizeCryptoSymbol(symbol: string): string | null {
  const trimmed = symbol.trim().toUpperCase();
  return SYMBOL.test(trimmed) ? trimmed : null;
}

/**
The message of a thrown error, or the fallback when something else was thrown. Uses instanceof rather than Error.isError, which Node 22 and older browsers don't have.
*/
export function errorMessage(error: unknown, fallback: string): string {
  // eslint-disable-next-line unicorn/prefer-error-is-error -- Error.isError is missing on Node 22 and older browsers
  return error instanceof Error ? error.message : fallback;
}

const SMALL_PRICE = 1;
const SMALL_PRICE_DIGITS = 4;

/**
"$82,076.00", and coins under a dollar keep enough digits to move: "$0.0001234".
*/
export function formatCryptoPrice(value: number, currency: string): string {
  const isSmall = Math.abs(value) < SMALL_PRICE && value !== 0;
  const format = new Intl.NumberFormat("en-US", {
    currency,
    style: "currency",
    ...(isSmall
      ? { maximumSignificantDigits: SMALL_PRICE_DIGITS }
      : { maximumFractionDigits: 2, minimumFractionDigits: 2 }),
  });
  return format.format(value);
}

/**
"$1.65T", "$30.99B".
*/
export function formatCompactMoney(value: number, currency: string): string {
  const format = new Intl.NumberFormat("en-US", {
    currency,
    maximumFractionDigits: 2,
    notation: "compact",
    style: "currency",
  });
  return format.format(value);
}

const LARGE_PERCENT = 1000;

/**
"2.34%", and all-time gains read "66,011%" rather than "66011.47%".
*/
export function formatPercent(value: number): string {
  const size = Math.abs(value);
  const format = new Intl.NumberFormat("en-US", {
    maximumFractionDigits: size >= LARGE_PERCENT ? 0 : 2,
    minimumFractionDigits: size >= LARGE_PERCENT ? 0 : 2,
  });
  return `${format.format(size)}%`;
}

/**
One sentence the model (or a screen reader) can use to describe the card.
*/
export function summarizeCrypto(data: CryptoData): string {
  const direction = data.changePercent >= 0 ? "up" : "down";
  return `${data.name} (${data.symbol}) is at ${formatCryptoPrice(data.price, data.currency)}, ${direction} ${formatPercent(data.changePercent)} over ${RANGE_PERIOD[data.range]}. Market cap ${formatCompactMoney(data.marketCap, data.currency)}, 24-hour volume ${formatCompactMoney(data.volume24h, data.currency)}.`;
}

